    if len(baseball_field_patches) > 1:
        baseball_field_patches = [depth_order(baseball_field_patches)[0]]

    # Find the batter holding a bat on a baseball field
    for batter in batter_patches:
        for bat in bat_patches:
            if any(distance_3d(batter, field) < distance_3d(bat, field) for field in baseball_field_patches):
                return batter

    return image_patch
